import React, { useState, useEffect, useCallback, useMemo } from "react";
import { Swiper, SwiperSlide } from "swiper/react";
import { Autoplay } from "swiper";
import "swiper/css";
import "swiper/css/scrollbar";
import axios from "axios";

// Components
import CategoryCard from "../CategoryCard/CategoryCard";
import DisplayedProduct from "./DisplayedProduct";

const MainProducts = () => {
  // Variables for product and category data
  const [productShown, setProductShown] = useState(-1);
  const [category, setCategory] = useState([]);

  // Fetch category list only once on mount
  useEffect(() => {
    axios
      .get(process.env.REACT_APP_SERVER + "/api/homeCategoryList/")
      .then((data) => {
        setCategory(data["data"]["data"]);
      })
      .catch((error) => console.log(error));
  }, []);

  // Memoize so CategoryCard children don't get a new function ref on every render
  const handleSetProductShown = useCallback((index) => {
    setProductShown(index);
  }, []);

  // Compute once, not on every render
  const slidesPerView = useMemo(() => (window.innerWidth > 640 ? 4 : 2), []);

  return (
    <>
      {/* Heading */}
      <div className="box h-[5rem] w-[25rem] relative flex justify-start items-start ml-[2rem] group mt-6">
        <div className="h-12 w-1.5 bg-[#004B95] absolute mr-[1rem] origin-left group-hover:w-[16rem] duration-300 group"></div>
        <p className="text-[24px] absolute font-bold text-[#004B95] mt-[0.5rem] ml-[1rem] group-hover:text-white group-hover:translate-x-5 duration-300">
          Our Products
        </p>
      </div>
      <div className="flex p-[10px] gap-[15px] max-w-full" id="ourProducts">
        {/* Products to be displayed when hover over category */}
        <DisplayedProduct
          productShown={productShown}
          data={category[productShown]}
        />
        <Swiper
          className="rounded-lg pb-0"
          slidesPerView={slidesPerView}
          spaceBetween={20}
          autoplay={{
            delay: 3500,           // slower = fewer repaints competing with scroll
            disableOnInteraction: true, // pause when user hovers/touches
          }}
          loop={true}
          modules={[Autoplay]}
        >

          {category.map((item, index) => {
            if (index % 2 === 0) {
              let img = "";
              try {
                img = process.env.REACT_APP_SERVER + item.products[0][1];
              } catch {
                img = "";
              }
              let img1 = "";
              try {
                img1 =
                  process.env.REACT_APP_SERVER +
                  category[index + 1].products[0][1];
              } catch {
                img1 = "";
              }
              let component1 = <div></div>;
              try {
                /* Category card 1 */
                component1 = (
                  <CategoryCard
                    key={`cat-${index}`}
                    index={index}
                    link={item.categoryLink}
                    title={item.categoryName}
                    description={item.discription}
                    img={img}
                    rating={category[index].products[0][5]}
                    stars={category[index].products[0][4]}
                    setProductShown={handleSetProductShown}
                  />
                );
              } catch {}
              let component2 = <div></div>;
              try {
                // Category card 2
                component2 = (
                  <CategoryCard
                    key={`cat-${index + 1}`}
                    index={index + 1}
                    link={category[index + 1].categoryLink}
                    title={category[index + 1].categoryName}
                    description={category[index + 1].discription}
                    img={img1}
                    rating={category[index + 1].products[0][5]}
                    stars={category[index + 1].products[0][4]}
                    setProductShown={handleSetProductShown}
                  />
                );
              } catch {}
              return (
                // Slider for categories
                <SwiperSlide key={index}>
                  {component1}
                  {component2}
                </SwiperSlide>
              );
            } else {
              return null;
            }
          })}
        </Swiper>
      </div>
    </>
  );
};

export default MainProducts;
